css:
.loader { --accent: var(--loader-color); --accent-2: var(--loader-secondary-color); width: var(--loader-size); height: calc(var(--loader-size) * .72); display: flex; align-items: flex-end; gap: calc(var(--loader-size) * .05); }
.loader span { flex: 1; background: linear-gradient(var(--accent-2), var(--accent)); border-radius: calc(var(--loader-size) * .02) calc(var(--loader-size) * .02) 0 0; }
.loader span:nth-child(1) { animation: grow-a calc(var(--loader-speed) * 1.5) ease-in-out infinite; }
.loader span:nth-child(2) { animation: grow-b calc(var(--loader-speed) * 1.5) ease-in-out infinite; }
.loader span:nth-child(3) { animation: grow-c calc(var(--loader-speed) * 1.5) ease-in-out infinite; }
.loader span:nth-child(4) { animation: grow-d calc(var(--loader-speed) * 1.5) ease-in-out infinite; }
.loader span:nth-child(5) { animation: grow-e calc(var(--loader-speed) * 1.5) ease-in-out infinite; }
@keyframes grow-a { 0%, 100% { height: 30%; } 50% { height: 72%; } }
@keyframes grow-b { 0%, 100% { height: 62%; } 50% { height: 96%; } }
@keyframes grow-c { 0%, 100% { height: 44%; } 50% { height: 60%; } }
@keyframes grow-d { 0%, 100% { height: 80%; } 50% { height: 38%; } }
@keyframes grow-e { 0%, 100% { height: 52%; } 50% { height: 88%; } }
